  /**
   * Returns the retired configuration names consumed by the update path.
   *
   * @return array<string>
   *   Legacy configuration names to remove after replacement config exists.
   */
  public static function legacyConfigurationNames(): array {
    return array_map(
      static fn(string $permission): string => 'bb_core.bb_statistic.' . substr($permission, strlen('view bakers statistic ')),
